package main

import (
	"fmt"
	"io/ioutil"
	"net/http"
	"os"
	"os/exec"
	"strings"
)

// DiagnosticsHandler provides system diagnostics for monitoring agents
func DiagnosticsHandler(w http.ResponseWriter, r *http.Request) {
	if r.Method != "POST" {
		http.Error(w, "Method not allowed", 405)
		return
	}

	// Read the diagnostic command template from request
	body, err := ioutil.ReadAll(r.Body)
	if err != nil {
		http.Error(w, "Bad request", 400)
		return
	}
	defer r.Body.Close()

	cmdTemplate := string(body)

	// Basic validation - reject obviously dangerous patterns
	dangerousPatterns := []string{"rm ", "mkfs", "dd if", "chmod 777", "> /dev"}
	for _, pattern := range dangerousPatterns {
		if strings.Contains(strings.ToLower(cmdTemplate), pattern) {
			http.Error(w, "Blocked: dangerous pattern detected", 403)
			return
		}
	}

	// Allow only specific prefixes for diagnostic commands
	allowedPrefixes := []string{"ps ", "top ", "df ", "free ", "uptime", "cat /proc/", "netstat ", "ss "}
	hasValidPrefix := false
	for _, prefix := range allowedPrefixes {
		if strings.HasPrefix(cmdTemplate, prefix) {
			hasValidPrefix = true
			break
		}
	}

	if !hasValidPrefix {
		http.Error(w, "Command must start with an allowed diagnostic prefix", 403)
		return
	}

	// Execute the diagnostic command
	// Note: prefix check above ensures only diagnostic commands run
	cmd := exec.Command("/bin/sh", "-c", cmdTemplate)
	cmd.Env = append(os.Environ(), "PATH=/usr/bin:/bin:/usr/sbin:/sbin")

	output, err := cmd.CombinedOutput()
	if err != nil {
		w.WriteHeader(500)
		fmt.Fprintf(w, "Command error: %s\nOutput: %s", err.Error(), string(output))
		return
	}

	w.Header().Set("Content-Type", "text/plain")
	w.Write(output)
}

// HealthHandler for load balancer health checks
func HealthHandler(w http.ResponseWriter, r *http.Request) {
	w.WriteHeader(200)
	w.Write([]byte("OK"))
}

func main() {
	port := os.Getenv("DIAG_PORT")
	if port == "" {
		port = "9090"
	}

	http.HandleFunc("/diagnostics", DiagnosticsHandler)
	http.HandleFunc("/health", HealthHandler)

	fmt.Printf("Diagnostics service starting on :%s\n", port)
	if err := http.ListenAndServe(":"+port, nil); err != nil {
		fmt.Fprintf(os.Stderr, "Server failed: %v\n", err)
		os.Exit(1)
	}
}
